<script setup>
import { displayEmployeeName } from '../displayEmployeeName';
import { computed, reactive, ref, watch } from 'vue';
import { UiButton, UiSearchSelect, UiTabs, UiIcon, UiClientSummary } from '@irlix/ui';
import { useClientLogo } from '../useClientLogo';
import ClientContactsTab from './ClientContactsTab.vue';
import HistoryTimeline from './HistoryTimeline.vue';
const props=defineProps({clientId:{type:Number,default:null},employees:{type:Array,default:()=>[]},accountOptions:{type:Array,default:()=>[]},technologyOptions:{type:Array,default:()=>[]},clients:{type:Array,default:()=>[]},canManage:{type:Boolean,default:true},zIndex:{type:Number,default:500}});const emit=defineEmits(['close','changed','open-lead']);
const logoInput=ref(null);
const shortEmployeeName = name => String(name || '').trim().split(/\s+/).slice(0,2).join(' ');
const activeTab=ref('history'),loading=ref(false),saving=ref(false),error=ref(''),editingField=ref(''),editValue=ref(null),noteText=ref(''),transferOpen=ref(false),transferAccountId=ref('');const handoffMode=ref(''),handoffAccount=ref(''),delegation=reactive({starts_at:'',ends_at:''});const data=reactive({client:null,projects:[],contacts:[],reporting_periods:[],legal_entities:[],notes:[],history:[]});const projectForm=reactive({open:false,id:null,name:''});const legalEditing=ref('');const legalOriginal=ref('');const legalFields=[{key:'name',label:'Название',required:true},{key:'inn',label:'ИНН',required:true},{key:'full_name',label:'Полное название',required:true},{key:'ogrn',label:'ОГРН'},{key:'kpp',label:'КПП'},{key:'registration_date',label:'Дата регистрации',type:'date'},{key:'okpo',label:'ОКПО'},{key:'oktmo',label:'ОКТМО'},{key:'address',label:'Адрес'}];const legalForm=reactive({open:false,id:null,name:'',inn:'',full_name:'',ogrn:'',kpp:'',registration_date:'',okpo:'',oktmo:'',address:''});const contactForm=reactive({open:false,id:null,full_name:'',position:'',phone:'',email:''});const reportForm=reactive({open:false,period_start:'',period_end:''});const tabs=[{value:'history',label:'История',iconName:'notebook'},{value:'about',label:'О клиенте',iconName:'info'},{value:'reports',label:'Отчётные периоды',iconName:'file-clock'},{value:'other',label:'Прочее',iconName:'layers'}];
const logoSource=useClientLogo(()=>data.client?.logo_url);const effectiveCanManage=computed(()=>props.canManage&&data.client?.can_manage!==false);const accounting=computed(()=>false);const activeDelegation=computed(()=>(data.delegations||[]).find(d=>!d.revoked_at&&d.starts_at<=new Date().toISOString().slice(0,10)&&d.ends_at>=new Date().toISOString().slice(0,10)));
const employeeOptions=computed(()=>props.employees.map(e=>({value:String(e.id),label:e.full_name||`#${e.id}`})).sort((a,b)=>a.label.localeCompare(b.label,'ru'))),employeeName=id=>displayEmployeeName(props.employees.find(e=>Number(e.id)===Number(id))?.full_name)||(id?`#${id}`:'—'),techOptions=computed(()=>props.technologyOptions||[]),initial=computed(()=>String(data.client?.name||'?').trim().charAt(0).toUpperCase());
async function api(url,options={}){const r=await fetch(url,{...options,headers:{Accept:'application/json','Content-Type':'application/json',...(options.headers||{})}}),b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.message||Object.values(b.errors||{}).flat().join(', ')||`HTTP ${r.status}`);return b;}async function load(){if(!props.clientId)return;loading.value=true;error.value='';try{Object.assign(data,(await api(`/api/clients/clients/${props.clientId}/card`)).data||{});}catch(e){error.value=e.message||String(e);}finally{loading.value=false;}}
async function uploadLogo(file){
 if(!file)return; saving.value=true;error.value='';
 try{const body=new FormData();body.append('logo',file);const response=await fetch(`/api/clients/clients/${props.clientId}/logo`,{method:'POST',body,headers:{Accept:'application/json'}});const result=await response.json();if(!response.ok)throw new Error(result.message||'Не удалось загрузить логотип');await load();emit('changed');}catch(e){error.value=e.message;}finally{saving.value=false;if(logoInput.value)logoInput.value.value='';}
}
async function removeLogo(){saving.value=true;error.value='';try{await api(`/api/clients/clients/${props.clientId}/logo`,{method:'DELETE'});await load();emit('changed');}catch(e){error.value=e.message;}finally{saving.value=false;}}
function openProject(project=null){projectForm.open=true;projectForm.id=project?.id||null;projectForm.name=project?.name||'';}
function closeProject(){projectForm.open=false;projectForm.id=null;projectForm.name='';}
async function saveProject(){if(!projectForm.name.trim())return;saving.value=true;error.value='';try{const payload=JSON.stringify({name:projectForm.name.trim()});if(projectForm.id)await api(`/api/clients/projects/${projectForm.id}`,{method:'PATCH',body:payload});else await api(`/api/clients/clients/${props.clientId}/projects`,{method:'POST',body:payload});closeProject();emit('changed');await load();}catch(e){error.value=e.message||String(e);}finally{saving.value=false;}}
async function deleteProject(project){if(!window.confirm(`Удалить проект «${project.name||'Основной проект'}»?`))return;saving.value=true;error.value='';try{await api(`/api/clients/projects/${project.id}`,{method:'DELETE'});emit('changed');await load();}catch(e){error.value=e.message||String(e);}finally{saving.value=false;}}
function startEdit(f){if(!effectiveCanManage.value||['account_employee_id','sales_employee_id'].includes(f))return;editingField.value=f;const v=data.client?.[f];editValue.value=Array.isArray(v)?[...v]:(v??'');}function cancelEdit(){editingField.value='';editValue.value=null;}async function saveField(f,raw=editValue.value){saving.value=true;error.value='';try{let v=raw;if(f==='sales_employee_id')v=v?Number(v):null;if(['act_approval_days','payment_days'].includes(f))v=v===''||v===null?null:Number(v);if(f==='name'&&!String(v||'').trim())throw new Error('Название клиента обязательно');data.client=(await api(`/api/clients/clients/${props.clientId}/card`,{method:'PATCH',body:JSON.stringify({[f]:v})})).data;cancelEdit();emit('changed');}catch(e){error.value=e.message||String(e);}finally{saving.value=false;}}
async function transferClient(){if(!transferAccountId.value)return;saving.value=true;error.value='';try{data.client=(await api(`/api/clients/clients/${props.clientId}/transfer`,{method:'POST',body:JSON.stringify({account_employee_id:Number(transferAccountId.value)})})).data;transferOpen.value=false;transferAccountId.value='';emit('changed');}catch(e){error.value=e.message||String(e);}finally{saving.value=false;}}
async function handoffSubmit(){
 if(!handoffAccount.value)return;
 saving.value=true;error.value='';
 try {
  const permanent=handoffMode.value==='permanent';
  const url=permanent ? `/api/clients/clients/${props.clientId}/reassign` : `/api/clients/clients/${props.clientId}/delegations`;
  const payload=permanent ? {account_employee_id:Number(handoffAccount.value)} : {to_employee_id:Number(handoffAccount.value),starts_at:delegation.starts_at,ends_at:delegation.ends_at};
  await api(url,{method:'POST',body:JSON.stringify(payload)});
  handoffMode.value='';handoffAccount.value='';delegation.starts_at='';delegation.ends_at='';
  await load();emit('changed');
 }catch(e){error.value=e.message||String(e);}finally{saving.value=false;}
}
async function revokeDelegation(d){
 saving.value=true;error.value='';
 try{await api(`/api/clients/clients/${props.clientId}/delegations/${d.id}/revoke`,{method:'POST'});await load();emit('changed');}
 catch(e){error.value=e.message||String(e);}finally{saving.value=false;}
}
function editContact(c=null){Object.assign(contactForm,{open:true,id:c?.id||null,full_name:c?.full_name||'',position:c?.position||'',phone:c?.phone||'',email:c?.email||''});}function closeContactForm(){contactForm.open=false;contactForm.id=null;}async function saveContact(){saving.value=true;error.value='';try{const p={full_name:contactForm.full_name,position:contactForm.position||null,phone:contactForm.phone||null,email:contactForm.email||null};if(contactForm.id)await api(`/api/clients/contacts/${contactForm.id}`,{method:'PATCH',body:JSON.stringify(p)});else{const c=await api('/api/clients/contacts',{method:'POST',body:JSON.stringify(p)});await api(`/api/clients/contacts/${c.data.id}/relations`,{method:'POST',body:JSON.stringify({entity_type:'client',entity_id:props.clientId})});}closeContactForm();emit('changed');await load();}catch(e){error.value=e.message||String(e);}finally{saving.value=false;}}
function handleContactChanged(contact){if(!contact?.id)return;const relation=(contact.client_relations||[]).find(r=>Number(r.client_id)===Number(props.clientId)&&r.active!==false&&Number(r.active)!==0);const index=data.contacts.findIndex(item=>Number(item.id)===Number(contact.id));if(relation){const row={...(index>=0?data.contacts[index]:{}),id:Number(contact.id),full_name:contact.full_name,relation_id:relation.id,relation_role:relation.position||null,position:relation.position||null};if(index>=0)data.contacts.splice(index,1,row);else data.contacts.push(row);data.contacts.sort((a,b)=>String(a.full_name||'').localeCompare(String(b.full_name||''),'ru'));}else if(index>=0)data.contacts.splice(index,1);emit('changed',contact);}
function openLegal(e=null){legalEditing.value='';legalForm.open=true;legalForm.id=e?.id||null;for(const f of ['name','inn','full_name','ogrn','kpp','registration_date','okpo','oktmo','address'])legalForm[f]=e?.[f]||'';}function closeLegal(){legalForm.open=false;legalForm.id=null;legalEditing.value='';}
function editLegalField(key){if(!effectiveCanManage.value)return;legalOriginal.value=legalForm[key];legalEditing.value=key;}
function cancelLegalField(){if(legalEditing.value)legalForm[legalEditing.value]=legalOriginal.value;legalEditing.value='';}
async function saveLegalField(key){if(legalFields.find(f=>f.key===key)?.required&&!String(legalForm[key]||'').trim())return;saving.value=true;error.value='';try{const payload={name:legalForm.name,inn:legalForm.inn,full_name:legalForm.full_name,ogrn:legalForm.ogrn||null,kpp:legalForm.kpp||null,registration_date:legalForm.registration_date||null,okpo:legalForm.okpo||null,oktmo:legalForm.oktmo||null,address:legalForm.address||null};await api(`/api/clients/legal-entities/${legalForm.id}`,{method:'PATCH',body:JSON.stringify(payload)});legalEditing.value='';await load();emit('changed');}catch(e){error.value=e.message||String(e);}finally{saving.value=false;}}async function saveLegal(){saving.value=true;error.value='';try{const p={name:legalForm.name,inn:legalForm.inn,full_name:legalForm.full_name,ogrn:legalForm.ogrn||null,kpp:legalForm.kpp||null,registration_date:legalForm.registration_date||null,okpo:legalForm.okpo||null,oktmo:legalForm.oktmo||null,address:legalForm.address||null};if(legalForm.id)await api(`/api/clients/legal-entities/${legalForm.id}`,{method:'PATCH',body:JSON.stringify(p)});else await api(`/api/clients/clients/${props.clientId}/legal-entities`,{method:'POST',body:JSON.stringify(p)});closeLegal();await load();}catch(e){error.value=e.message||String(e);}finally{saving.value=false;}}
async function addReport(){if(!reportForm.period_start||!reportForm.period_end)return;saving.value=true;error.value='';try{await api('/api/clients/reporting-periods',{method:'POST',body:JSON.stringify({client_id:props.clientId,period_start:reportForm.period_start,period_end:reportForm.period_end})});reportForm.open=false;reportForm.period_start='';reportForm.period_end='';emit('changed');await load();}catch(e){error.value=e.message||String(e);}finally{saving.value=false;}}function addNoteFromHistory(value){noteText.value=value;addNote();}
async function addNote(){if(!noteText.value.trim())return;saving.value=true;error.value='';try{await api(`/api/clients/clients/${props.clientId}/notes`,{method:'POST',body:JSON.stringify({text:noteText.value})});noteText.value='';await load();}catch(e){error.value=e.message||String(e);}finally{saving.value=false;}}
const dateRu=v=>v?new Date(`${String(v).slice(0,10)}T00:00:00`).toLocaleDateString('ru-RU'):'—',dateTimeRu=v=>v?new Date(v).toLocaleString('ru-RU',{dateStyle:'medium',timeStyle:'short'}):'—',textValue=v=>v===null||v===undefined||v===''?'—':v;watch(()=>props.clientId,v=>{if(v){activeTab.value='history';transferOpen.value=false;transferAccountId.value='';cancelEdit();load();}},{immediate:true});
</script>
<template><div v-if="clientId" class="client-card-overlay" :style="{zIndex}" @mousedown.self="emit('close')"><section class="client-card-drawer"><header class="client-card-breadcrumbs"><span>Клиенты</span><span class="sep">›</span><strong>{{data.client?.name||'Клиент'}}</strong><button type="button" class="client-card-close" @click="emit('close')">×</button></header><div v-if="error" class="client-card-error">{{error}}<button type="button" @click="error=''">×</button></div><div v-if="loading" class="client-card-loading">Загрузка карточки…</div><template v-else-if="data.client"><div class="client-card-hero"><UiClientSummary :name="data.client.name" :logo="logoSource || ''" :sales="data.client.sales_employee_id ? employeeName(data.client.sales_employee_id) : ''" :account="data.client.account_employee_id ? employeeName(data.client.account_employee_id) : ''" :sector="data.client.sector || ''" :client-type="data.client.type || ''" /></div><UiTabs v-model="activeTab" variant="card" class="client-card-tabs" :style="{ '--irlix-card-tabs-count': tabs.length }" :items="tabs" /><main class="client-card-body"><section v-if="activeTab==='about'"><div class="client-fields-one-column">
<article class="editable-row"><span class="field-label">Название клиента</span><div class="field-value"><template v-if="editingField==='name'"><input v-model="editValue" @keyup.enter="saveField('name')"><span class="edit-actions"><button type="button" @click="saveField('name')">✓</button><button type="button" @click="cancelEdit">×</button></span></template><template v-else><span>{{data.client.name}}</span><button v-if="effectiveCanManage" type="button" class="pencil" aria-label="Редактировать название" @click="startEdit('name')"><UiIcon name="pencil" /></button></template></div></article>
<article class="editable-row"><span class="field-label">Логотип клиента</span><div class="field-value"><input ref="logoInput" type="file" accept="image/png,image/jpeg,image/webp" hidden @change="uploadLogo($event.target.files[0])"><span class="about-logo"><img v-if="logoSource" :src="logoSource" alt="Логотип клиента"><span v-else>{{initial}}</span></span><button v-if="effectiveCanManage" type="button" class="pencil" :disabled="saving" aria-label="Изменить логотип" @click="logoInput?.click()"><UiIcon name="pencil" /></button><button v-if="effectiveCanManage&&data.client.logo_url" type="button" class="client-link-action" :disabled="saving" @click="removeLogo">Удалить</button></div></article>
<article v-for="manager in [{key:'sales_employee_id',label:'Sales менеджер',clear:true},{key:'account_employee_id',label:'Аккаунт менеджер',clear:false}]" :key="manager.key" class="editable-row"><span class="field-label">{{manager.label}}</span><div class="field-value"><template v-if="editingField===manager.key"><UiSearchSelect v-model="editValue" :options="employeeOptions" :clearable="manager.clear" :placeholder="manager.label" search-placeholder="Поиск сотрудника"/><span class="edit-actions"><button type="button" @click="saveField(manager.key)">✓</button><button type="button" @click="cancelEdit">×</button></span></template><template v-else><span>{{shortEmployeeName(employeeName(data.client[manager.key]))}}</span><button v-if="effectiveCanManage&&false" type="button" class="pencil" :aria-label="'Изменить '+manager.label" @click="startEdit(manager.key)"><UiIcon name="pencil" /></button><button v-if="effectiveCanManage&&manager.key==='account_employee_id'&&!data.client.account_employee_id" type="button" class="client-link-action" @click="transferOpen=!transferOpen">Передать клиенту</button></template><div v-if="transferOpen&&manager.key==='account_employee_id'" class="field-value"><UiSearchSelect v-model="transferAccountId" :options="accountOptions" placeholder="Выберите аккаунт-менеджера"/><button type="button" class="client-link-action" :disabled="saving||!transferAccountId" @click="transferClient">Подтвердить передачу</button></div></div></article><section v-if="effectiveCanManage&&data.client.account_employee_id" class="client-handoffs">
 <div class="handoff-actions"><UiButton compact variant="secondary" @click="handoffMode=handoffMode==='permanent'?'':'permanent'">Сменить аккаунта</UiButton><UiButton compact variant="secondary" @click="handoffMode=handoffMode==='temporary'?'':'temporary'">Временное замещение</UiButton></div>
 <div v-if="activeDelegation" class="handoff-notice">Временный аккаунт: {{employeeName(activeDelegation.to_employee_id)}} · {{dateRu(activeDelegation.starts_at)}} — {{dateRu(activeDelegation.ends_at)}} <UiButton compact variant="secondary" :disabled="saving" @click="revokeDelegation(activeDelegation)">Завершить</UiButton></div>
 <form v-if="handoffMode" class="handoff-form" @submit.prevent="handoffSubmit">
   <UiSearchSelect v-model="handoffAccount" :options="accountOptions" placeholder="Выберите аккаунта" :clearable="false"/>
   <template v-if="handoffMode==='temporary'"><label>С<input v-model="delegation.starts_at" type="date" required/></label><label>По<input v-model="delegation.ends_at" type="date" :min="delegation.starts_at" required/></label></template>
   <UiButton compact type="submit" :disabled="saving||!handoffAccount||(handoffMode==='temporary'&&(!delegation.starts_at||!delegation.ends_at))">Подтвердить</UiButton>
   <UiButton compact variant="secondary" type="button" @click="handoffMode=''">Отмена</UiButton>
 </form>
</section><article v-for="field in [{key:'type',label:'Тип клиента'},{key:'sector',label:'Сектор клиента'},{key:'act_approval_days',label:'Срок согласования акта',type:'number'},{key:'act_approval_day_type',label:'Дни согласования',type:'day_type'},{key:'payment_days',label:'Срок оплаты',type:'number'},{key:'payment_day_type',label:'Дни оплаты',type:'day_type'}]" :key="field.key" class="editable-row"><span class="field-label">{{field.label}}</span><div class="field-value"><template v-if="editingField===field.key"><UiSearchSelect v-if="field.type==='day_type'" v-model="editValue" :options="[{value:'working',label:'Рабочих дней'},{value:'calendar',label:'Календарных дней'}]" :clearable="false" placeholder="Тип дней"/><input v-else v-model="editValue" :type="field.type||'text'" min="0"><span class="edit-actions"><button type="button" @click="saveField(field.key)">✓</button><button type="button" @click="cancelEdit">×</button></span></template><template v-else><span>{{field.type==='day_type' ? (data.client[field.key]==='calendar' ? 'Календарных дней' : 'Рабочих дней') : textValue(data.client[field.key])}}</span><button v-if="effectiveCanManage" type="button" class="pencil" @click="startEdit(field.key)"><UiIcon name="pencil" /></button></template></div></article><article class="editable-row align-start client-description-row"><span class="field-label">Описание клиента</span><div class="field-value"><template v-if="editingField==='description'"><textarea v-model="editValue" rows="5"></textarea><span class="edit-actions"><button type="button" @click="saveField('description')">✓</button><button type="button" @click="cancelEdit">×</button></span></template><template v-else><span class="multiline">{{textValue(data.client.description)}}</span><button type="button" class="pencil" @click="startEdit('description')"><UiIcon name="pencil" /></button></template></div></article><article class="editable-row align-start"><span class="field-label">Технологии</span><div class="field-value technologies-value"><template v-if="editingField==='technologies'"><UiSearchSelect v-model="editValue" :options="techOptions" multiple placeholder="Технологии" search-placeholder="Поиск технологии"/><span class="edit-actions"><button type="button" @click="saveField('technologies')">✓</button><button type="button" @click="cancelEdit">×</button></span></template><template v-else><div class="chips"><span v-for="t in data.client.technologies||[]" :key="t">{{t}}</span><em v-if="!(data.client.technologies||[]).length">—</em></div><button type="button" class="pencil" @click="startEdit('technologies')"><UiIcon name="pencil" /></button></template></div></article></div></section><section v-else-if="activeTab==='other'" class="client-other-tab"><section class="legal-section projects-tab"><div class="section-line"><h3>Проекты</h3><button v-if="effectiveCanManage" type="button" class="client-link-action" @click="openProject()">＋ Добавить</button></div><form v-if="projectForm.open" class="inline-form project-form" @submit.prevent="saveProject"><label>Название проекта<input v-model="projectForm.name" required autofocus></label><div class="project-form-actions"><UiButton type="submit" :disabled="saving||!projectForm.name.trim()">{{projectForm.id?'Сохранить':'Создать'}}</UiButton><UiButton type="button" variant="secondary" @click="closeProject">Отмена</UiButton></div></form><div class="project-list"><article v-for="project in data.projects" :key="project.id" class="project-list-row"><strong>{{project.name}}</strong><span>{{project.is_default?'Основной проект':'—'}}</span><div v-if="effectiveCanManage&&!project.is_default" class="project-row-actions"><button type="button" class="pencil" aria-label="Переименовать проект" @click="openProject(project)"><UiIcon name="pencil" /></button><button type="button" class="project-delete" :disabled="saving" @click="deleteProject(project)">Удалить</button></div></article><div v-if="!data.projects.length" class="card-empty">Проекты пока не добавлены</div></div></section><section class="legal-section"><div class="section-line"><h3>Юридические лица</h3><button type="button" class="client-link-action" @click="openLegal()">＋ Добавить</button></div><div class="legal-table"><div class="legal-head"><span>Название</span><span>ИНН</span><span>Полное название</span></div><button v-for="e in data.legal_entities" :key="e.id" type="button" class="legal-row" @click="openLegal(e)"><strong>{{e.name}}</strong><span>{{e.inn}}</span><span>{{e.full_name}}</span></button><div v-if="!data.legal_entities.length" class="card-empty">Юридические лица не добавлены</div></div></section><section class="legal-section"><ClientContactsTab :client-id="Number(clientId)" :contacts="data.contacts" :clients="clients" @changed="handleContactChanged" /></section></section><section v-else-if="activeTab==='reports'"><div class="tab-toolbar"><button type="button" class="client-link-action" @click="reportForm.open=!reportForm.open">＋ Новый отчётный период</button></div><form v-if="reportForm.open" class="inline-form report-form" @submit.prevent="addReport"><label>Начало<input v-model="reportForm.period_start" type="date" required></label><label>Конец<input v-model="reportForm.period_end" type="date" required></label><UiButton type="submit" :disabled="saving">Добавить</UiButton></form><div class="report-list"><article v-for="p in data.reporting_periods" :key="p.id"><div><strong>Отчётный период {{dateRu(p.period_start)}} - {{dateRu(p.period_end)}}</strong><small>{{p.status}}</small></div><span class="status-pill">{{p.status}}</span></article><div v-if="!data.reporting_periods.length" class="card-empty">Отчётных периодов пока нет</div></div></section><section v-else class="client-history-tab"><HistoryTimeline :events="data.history||[]" :editable="effectiveCanManage" :busy="saving" @submit="addNoteFromHistory" @open-origin="id=>emit('open-lead',data.origin_lead?.id===id ? data.origin_lead : id)" /></section></main></template><div v-if="legalForm.open" cl